# Lectures d'altres assignatures per a Secundària (ESO), valencià (AVL).
# Cada una: (id, level, title, emoji, topics, text, [(prompt, options, correct, explanation)], {'subject', 'glossary'})
G = lambda *pairs: [list(p) for p in pairs]
R = [
 ('lectura_ca_eso_cellula', 5, 'La cèl·lula, la unitat de la vida', '🔬', ['ciencia', 'naturaleza'],
  'Tots els éssers vius, des d’un bacteri fins a una balena, estan formats per cèl·lules. La cèl·lula és la part més xicoteta d’un ésser viu que pot fer per si mateixa les funcions vitals: nutrició, relació i reproducció.\n\n'
  'Alguns éssers vius tenen una sola cèl·lula i s’anomenen unicel·lulars, com els bacteris. Altres, com les plantes i els animals, estan formats per milions de cèl·lules i s’anomenen pluricel·lulars.\n\n'
  'Quasi totes les cèl·lules tenen tres parts. La membrana és una capa fina que les envolta i deixa passar unes substàncies i altres no. El citoplasma és l’interior de la cèl·lula, una espècie de líquid espés on hi ha els orgànuls. El material genètic conté les instruccions perquè la cèl·lula funcione i es dividisca.\n\n'
  'Les cèl·lules animals i les vegetals s’assemblen, però tenen diferències. Les vegetals tenen una paret cel·lular rígida que els dona forma i cloroplasts, uns orgànuls verds on es fabrica l’aliment a partir de la llum del sol.',
  [('Què és la cèl·lula?', ['L’òrgan més gran del cos', 'La part més xicoteta d’un ésser viu que pot fer les funcions vitals', 'Una substància que fabriquen les plantes'], 1, 'És «la part més xicoteta d’un ésser viu que pot fer per si mateixa les funcions vitals».'),
   ('Com s’anomena un ésser viu format per una sola cèl·lula?', ['Pluricel·lular', 'Unicel·lular', 'Vegetal'], 1, '«Alguns éssers vius tenen una sola cèl·lula i s’anomenen unicel·lulars.»'),
   ('Quina part de la cèl·lula decideix quines substàncies entren i ixen?', ['La membrana', 'El citoplasma', 'El material genètic'], 0, 'La membrana «deixa passar unes substàncies i altres no».'),
   ('Per què una cèl·lula vegetal pot fabricar el seu aliment i una animal no?', ['Perquè és més gran', 'Perquè té cloroplasts', 'Perquè no té membrana'], 1, 'Als cloroplasts «es fabrica l’aliment a partir de la llum del sol».')],
  {'subject': 'bio', 'glossary': G(('membrana', 'Capa fina que envolta la cèl·lula i controla el que entra i ix.'), ('citoplasma', 'Interior de la cèl·lula, on hi ha els orgànuls.'), ('unicel·lular', 'Ésser viu format per una sola cèl·lula.'), ('cloroplast', 'Orgànul verd de les cèl·lules vegetals on es fa la fotosíntesi.'))}),
 ('lectura_ca_eso_neolitic', 5, 'El Neolític: aprendre a cultivar', '🌾', ['historia'],
  'Durant milers d’anys, els éssers humans van viure de la caça, la pesca i la recol·lecció de fruits. Eren nòmades: es desplaçaven d’un lloc a un altre seguint els animals i buscant aliment. Esta etapa s’anomena Paleolític.\n\n'
  'Fa uns 10.000 anys, en una zona del Pròxim Orient, alguns grups van descobrir que podien sembrar llavors i arreplegar la collita. També van començar a domesticar animals com la cabra, l’ovella o el bou. Havia començat el Neolític.\n\n'
  'L’agricultura i la ramaderia ho van canviar tot. Com que ja no necessitaven moure’s per a aconseguir menjar, moltes persones es van fer sedentàries i van construir els primers poblats, amb cases de fang i pedra. A més, de vegades obtenien més aliment del que necessitaven, i eixe excedent es podia guardar o intercanviar.\n\n'
  'Amb el temps van aparéixer nous oficis, com el de terrisser, que fabricava gerres de ceràmica per a emmagatzemar el gra, o el de teixidor. Per això molts historiadors parlen de la «revolució neolítica».',
  [('Com aconseguien aliment els éssers humans del Paleolític?', ['Amb l’agricultura i la ramaderia', 'Amb la caça, la pesca i la recol·lecció', 'Comprant-lo als poblats'], 1, '«Van viure de la caça, la pesca i la recol·lecció de fruits.»'),
   ('On i quan va començar el Neolític?', ['A Europa, fa 1.000 anys', 'Al Pròxim Orient, fa uns 10.000 anys', 'A Amèrica, fa 500 anys'], 1, '«Fa uns 10.000 anys, en una zona del Pròxim Orient…»'),
   ('Per què moltes persones es van fer sedentàries?', ['Perquè ja no necessitaven moure’s per a aconseguir menjar', 'Perquè feia massa fred per a viatjar', 'Perquè es van acabar els animals'], 0, '«Com que ja no necessitaven moure’s per a aconseguir menjar…»'),
   ('Per a què servien les gerres de ceràmica?', ['Per a decorar les cases', 'Per a emmagatzemar el gra', 'Per a caçar animals'], 1, 'El terrisser fabricava «gerres de ceràmica per a emmagatzemar el gra».')],
  {'subject': 'geohist', 'glossary': G(('nòmada', 'Persona o grup que no viu sempre en el mateix lloc.'), ('sedentari', 'Que viu sempre en el mateix lloc.'), ('domesticar', 'Acostumar un animal salvatge a viure amb les persones.'), ('excedent', 'El que sobra després de cobrir el que és necessari.'))}),
 ('lectura_ca_eso_climes', 5, 'Els climes de la Terra', '🌍', ['naturaleza'],
  'El temps atmosfèric és l’estat de l’atmosfera en un moment concret: hui plou, demà farà sol. El clima, en canvi, és el temps que sol fer en un lloc al llarg de molts anys.\n\n'
  'Els dos elements més importants del clima són la temperatura i les precipitacions, és a dir, la pluja o la neu que cau. Depenen sobretot de la latitud, que és la distància d’un lloc a l’equador. Prop de l’equador els raigs del sol arriben més directes i fa calor tot l’any; prop dels pols arriben inclinats i fa molt de fred.\n\n'
  'Per això la Terra es dividix en grans zones climàtiques. En la zona càlida, al voltant de l’equador, hi ha els climes equatorial, tropical i desèrtic. En les dues zones temperades, els estius i els hiverns són diferents; ací es troba el clima mediterrani, el de la Comunitat Valenciana. I en les dues zones fredes, prop dels pols, l’hivern és molt llarg i l’estiu, curt i fresc.\n\n'
  'Altres factors, com l’altitud o la proximitat de la mar, també hi influïxen: a la muntanya fa més fred i a la costa les temperatures són més suaus.',
  [('Quina diferència hi ha entre temps atmosfèric i clima?', ['No hi ha cap diferència', 'El temps és el que passa en un moment; el clima, el que sol passar durant molts anys', 'El clima només parla de la pluja'], 1, 'El clima és «el temps que sol fer en un lloc al llarg de molts anys».'),
   ('Per què fa calor tot l’any prop de l’equador?', ['Perquè hi ha més mar', 'Perquè els raigs del sol arriben més directes', 'Perquè hi ha muntanyes altes'], 1, '«Prop de l’equador els raigs del sol arriben més directes.»'),
   ('En quina zona climàtica està la Comunitat Valenciana?', ['En la zona càlida', 'En una zona temperada', 'En una zona freda'], 1, 'El clima mediterrani està en les zones temperades.'),
   ('Si puges a una muntanya alta a l’estiu, què és el més probable?', ['Que faça més fred que a la costa', 'Que faça més calor que a la platja', 'Que ploga sempre'], 0, 'Hi influïx l’altitud: «a la muntanya fa més fred».')],
  {'subject': 'geohist', 'glossary': G(('clima', 'Temps que sol fer en un lloc durant molts anys.'), ('precipitacions', 'Aigua que cau dels núvols: pluja, neu o calamarsa.'), ('latitud', 'Distància d’un lloc a l’equador.'), ('altitud', 'Altura d’un lloc sobre el nivell de la mar.'))}),
 ('lectura_ca_eso_materia', 6, 'Sòlid, líquid i gas', '🧊', ['ciencia'],
  'Tot el que ens envolta és matèria: l’aigua, l’aire, una taula o el nostre propi cos. La matèria està formada per partícules diminutes que no podem veure, i la manera com es mouen i s’unixen explica els seus tres estats principals.\n\n'
  'En els sòlids, les partícules estan molt juntes i quasi no es mouen; només vibren. Per això els sòlids tenen una forma i un volum fixos. En els líquids, les partícules estan juntes, però poden lliscar unes sobre les altres: els líquids tenen volum fix, però adopten la forma del recipient. En els gasos, les partícules estan molt separades i es mouen a gran velocitat en totes direccions, de manera que ocupen tot l’espai disponible.\n\n'
  'Una mateixa substància pot passar d’un estat a un altre si canvia la temperatura. Quan escalfem gel, les seues partícules es mouen cada vegada més i arriba un moment en què el sòlid es convertix en líquid: és la fusió. Si continuem escalfant, l’aigua bull i es transforma en vapor: és la vaporització. En refredar-se passa el contrari: el vapor es condensa en gotes i l’aigua líquida se solidifica quan es gela.\n\n'
  'Cada substància canvia d’estat a una temperatura concreta. L’aigua pura, per exemple, es fon a 0 °C i bull a 100 °C al nivell de la mar.',
  [('Per què un sòlid té forma fixa?', ['Perquè les seues partícules estan molt juntes i quasi no es mouen', 'Perquè les seues partícules estan molt separades', 'Perquè pesa més'], 0, '«Les partícules estan molt juntes i quasi no es mouen.»'),
   ('Quin estat adopta la forma del recipient però manté el volum?', ['El sòlid', 'El líquid', 'El gas'], 1, '«Els líquids tenen volum fix, però adopten la forma del recipient.»'),
   ('Com s’anomena el pas de sòlid a líquid?', ['Vaporització', 'Condensació', 'Fusió'], 2, '«El sòlid es convertix en líquid: és la fusió.»'),
   ('Quan s’entela l’espill del bany després d’una dutxa, què passa?', ['Fusió: l’espill es fon', 'Condensació: el vapor es convertix en gotes d’aigua', 'Solidificació: l’aigua es gela'], 1, 'El vapor toca l’espill fred i «es condensa en gotes».')],
  {'subject': 'fyq', 'glossary': G(('partícula', 'Part diminuta de què està formada la matèria.'), ('volum', 'Espai que ocupa un cos.'), ('fusió', 'Pas de sòlid a líquid.'), ('condensar-se', 'Passar de gas a líquid.'))}),
 ('lectura_ca_eso_feudalisme', 6, 'Senyors i llauradors a l’edat mitjana', '🏰', ['historia'],
  'A Europa, durant bona part de l’edat mitjana, la societat es va organitzar segons un sistema anomenat feudalisme. Després de la caiguda de l’Imperi romà, els reis eren dèbils i hi havia guerres i invasions sovint. Per a defendre’s, molts llauradors van buscar la protecció dels nobles més poderosos, els senyors.\n\n'
  'El senyor era l’amo d’un territori anomenat feu, que havia rebut del rei a canvi de fidelitat i ajuda militar. En el feu hi havia el seu castell, les terres de conreu i els llogarets dels llauradors. Els llauradors treballaven la terra i, a canvi de protecció, donaven al senyor una part de la collita, pagaven impostos i treballaven de franc en les seues terres alguns dies.\n\n'
  'La societat feudal es dividia en tres grups, anomenats estaments. Els nobles es dedicaven a la guerra; el clergat, format per bisbes, sacerdots i monjos, es dedicava a resar; i els llauradors, que eren la gran majoria, treballaven per a mantindre tothom. Es naixia en un estament i era molt difícil canviar de grup.\n\n'
  'A partir del segle XI, el creixement de les ciutats i del comerç va fer aparéixer un grup nou, la burgesia, formada per comerciants i artesans que no depenien de cap senyor.',
  [('Per què els llauradors van buscar la protecció dels senyors?', ['Perquè els reis eren dèbils i hi havia guerres i invasions', 'Perquè volien ser nobles', 'Perquè els senyors els pagaven un sou'], 0, '«Els reis eren dèbils i hi havia guerres i invasions sovint.»'),
   ('Què donaven els llauradors al senyor a canvi de protecció?', ['Armes i cavalls', 'Part de la collita, impostos i dies de treball', 'Res, la protecció era de franc'], 1, 'Donaven part de la collita, pagaven impostos i treballaven de franc alguns dies.'),
   ('Quin estament era el més nombrós?', ['La noblesa', 'El clergat', 'Els llauradors'], 2, '«Els llauradors, que eren la gran majoria…»'),
   ('Què tenia de nou la burgesia?', ['Que es dedicava a resar', 'Que no depenia de cap senyor', 'Que vivia als castells'], 1, 'Comerciants i artesans «que no depenien de cap senyor».')],
  {'subject': 'geohist', 'glossary': G(('feu', 'Territori que el rei donava a un noble a canvi de fidelitat.'), ('estament', 'Grup social tancat de l’edat mitjana: noblesa, clergat o llauradors.'), ('clergat', 'Conjunt de les persones dedicades a l’Església.'), ('burgesia', 'Grup de comerciants i artesans de les ciutats.'))}),
 ('lectura_ca_eso_poblacio', 6, 'Quants som al món?', '👥', ['vida'],
  'L’any 1800 vivien a la Terra uns mil milions de persones. Hui som més de huit mil milions. La demografia és la ciència que estudia com canvia la població, i per a fer-ho usa algunes dades bàsiques.\n\n'
  'La natalitat és el nombre de naixements en un any, i la mortalitat, el nombre de defuncions. Si naixen més persones de les que moren, la població creix: és el que s’anomena creixement natural. També hi influïxen les migracions: les persones que arriben a un país, els immigrants, i les que se’n van, els emigrants.\n\n'
  'La població no està repartida per igual. Hi ha zones molt poblades, com el sud i l’est d’Àsia, l’Europa occidental o moltes costes, perquè tenen un clima suau, terres fèrtils o molta activitat econòmica. Altres zones, com els deserts, les muntanyes altes o les regions polars, estan quasi buides perquè és molt difícil viure-hi.\n\n'
  'A més, cada país té una estructura diferent. En molts països d’Àfrica la població és jove, perquè naixen molts xiquets. A Espanya, en canvi, naixen pocs xiquets i l’esperança de vida és alta, així que la població està envellint: cada vegada hi ha més persones majors i menys joves.',
  [('Quantes persones viuen hui a la Terra, segons el text?', ['Uns mil milions', 'Més de huit mil milions', 'Uns cent milions'], 1, '«Hui som més de huit mil milions.»'),
   ('Quan creix la població per creixement natural?', ['Quan naixen més persones de les que moren', 'Quan arriben molts turistes', 'Quan hi ha més ciutats'], 0, '«Si naixen més persones de les que moren, la població creix.»'),
   ('Per què els deserts estan quasi buits?', ['Perquè està prohibit viure-hi', 'Perquè és molt difícil viure-hi', 'Perquè hi ha massa gent'], 1, '«Estan quasi buides perquè és molt difícil viure-hi.»'),
   ('Per què la població d’Espanya està envellint?', ['Perquè naixen pocs xiquets i la gent viu molts anys', 'Perquè naixen molts xiquets', 'Perquè tots els joves emigren'], 0, '«Naixen pocs xiquets i l’esperança de vida és alta.»')],
  {'subject': 'geohist', 'glossary': G(('demografia', 'Ciència que estudia la població.'), ('natalitat', 'Nombre de naixements en un temps i un lloc.'), ('mortalitat', 'Nombre de defuncions en un temps i un lloc.'), ('esperança de vida', 'Anys que, de mitjana, s’espera que visca una persona.'))}),
 ('lectura_ca_eso_digestio', 7, 'El viatge dels aliments', '🍎', ['ciencia'],
  'Quan mengem un entrepà, comença un llarg viatge. L’aparell digestiu transforma els aliments en substàncies molt xicotetes, els nutrients, que el cos pot absorbir i utilitzar per a obtindre energia, créixer i reparar els teixits.\n\n'
  'Tot comença a la boca. Les dents trituren el menjar i la saliva l’humiteja i comença a descompondre alguns nutrients, com el midó del pa. Es forma així el bol alimentari, que empassem i que baixa per l’esòfag gràcies als moviments dels seus músculs.\n\n'
  'A l’estómac, el bol es mescla durant unes hores amb els sucs gàstrics, que són molt àcids, i es convertix en una espècie de farinetes anomenades quim. Després passa a l’intestí prim, un tub d’uns set metres plegat dins de l’abdomen. Allí actuen els sucs que fabriquen el fetge i el pàncrees, i la digestió es completa. Les parets de l’intestí prim estan cobertes de xicotets plecs, les vellositats, a través de les quals els nutrients passen a la sang.\n\n'
  'El que no s’ha pogut aprofitar arriba a l’intestí gros, on s’absorbix gran part de l’aigua. Les restes formen els excrements, que s’expulsen per l’anus. Per això és important beure aigua i menjar fibra, que ajuda que este últim tram funcione bé.',
  [('Per a què servix l’aparell digestiu?', ['Per a transportar l’oxigen', 'Per a transformar els aliments en nutrients que el cos puga usar', 'Per a eliminar el diòxid de carboni'], 1, 'Transforma els aliments en nutrients que el cos pot absorbir i utilitzar.'),
   ('On es forma el quim?', ['A la boca', 'A l’estómac', 'A l’intestí gros'], 1, 'A l’estómac el bol «es convertix en una espècie de farinetes anomenades quim».'),
   ('Per on passen els nutrients a la sang?', ['Per les vellositats de l’intestí prim', 'Per l’esòfag', 'Per les dents'], 0, 'Les vellositats, «a través de les quals els nutrients passen a la sang».'),
   ('Segons el text, per què convé menjar fibra?', ['Perquè dona molta energia', 'Perquè ajuda que l’intestí gros funcione bé', 'Perquè substituïx l’aigua'], 1, 'La fibra «ajuda que este últim tram funcione bé».')],
  {'subject': 'bio', 'glossary': G(('nutrient', 'Substància dels aliments que el cos utilitza.'), ('bol alimentari', 'Massa de menjar mastegat i mesclat amb saliva.'), ('quim', 'Farinetes en què es convertix l’aliment a l’estómac.'), ('vellositats', 'Plecs de l’intestí prim per on els nutrients passen a la sang.'))}),
 ('lectura_ca_eso_atom', 7, 'Dins de l’àtom', '⚛️', ['ciencia'],
  'Fa uns 2.400 anys, el filòsof grec Demòcrit va pensar que, si partim un objecte una vegada i una altra, al final arribaríem a un tros que ja no es podria dividir. El va anomenar àtom, que en grec significa «indivisible». Durant segles va ser només una idea, però hui sabem que tota la matèria està formada per àtoms, i que estos sí que tenen parts.\n\n'
  'Al centre de l’àtom hi ha el nucli, molt xicotet i amb quasi tota la massa. En el nucli hi ha protons, que tenen càrrega elèctrica positiva, i neutrons, que no tenen càrrega. Al voltant del nucli es mouen els electrons, molt més lleugers i amb càrrega negativa. Com que un àtom té tants electrons com protons, en conjunt és neutre.\n\n'
  'El que distingix un element químic d’un altre és el nombre de protons, anomenat nombre atòmic. Tots els àtoms d’hidrogen tenen un protó; tots els de carboni, sis; i tots els d’oxigen, huit.\n\n'
  'En el segle XIX, el químic rus Dmitri Mendeléiev va ordenar els elements coneguts en una taula segons les seues propietats. Va deixar buits per a elements que encara no s’havien descobert i va predir com serien. Quan es van trobar, les seues prediccions van resultar encertades. La seua idea és la base de la taula periòdica que s’usa hui, amb més de cent elements.',
  [('Què significa «àtom» en grec?', ['Xicotet', 'Indivisible', 'Elèctric'], 1, 'Àtom «en grec significa “indivisible”».'),
   ('Quina càrrega tenen els electrons?', ['Positiva', 'Negativa', 'No tenen càrrega'], 1, 'Els electrons són «molt més lleugers i amb càrrega negativa».'),
   ('Què distingix un element químic d’un altre?', ['El nombre de protons', 'El color', 'La grandària de l’àtom'], 0, '«El que distingix un element químic d’un altre és el nombre de protons.»'),
   ('Per què va ser important que Mendeléiev deixara buits en la taula?', ['Perquè així la taula era més bonica', 'Perquè va permetre predir elements que encara no es coneixien', 'Perquè no sabia ordenar els elements'], 1, 'Va predir com serien eixos elements i va encertar quan es van descobrir.')],
  {'subject': 'fyq', 'glossary': G(('àtom', 'Partícula molt xicoteta que forma la matèria.'), ('nucli', 'Centre de l’àtom, on hi ha els protons i els neutrons.'), ('nombre atòmic', 'Nombre de protons d’un àtom.'), ('element químic', 'Substància formada per àtoms amb el mateix nombre de protons.'))}),
 ('lectura_ca_eso_sectors', 7, 'En què treballem?', '🏭', ['vida', 'tecnologia'],
  'Les activitats econòmiques són les que fan les persones per a produir béns i oferir serveis. Per a estudiar-les, s’agrupen en tres sectors.\n\n'
  'El sector primari obté els recursos directament de la natura: l’agricultura, la ramaderia, la pesca i l’explotació dels boscos. Els cítrics de la Comunitat Valenciana o l’arròs de l’Albufera són productes del sector primari.\n\n'
  'El sector secundari transforma eixes matèries primeres en productes elaborats. Inclou la indústria, la construcció i la producció d’energia. Una fàbrica que convertix el fang en taulells, com les de Castelló, o una que fabrica cotxes pertany a este sector.\n\n'
  'El sector terciari no produïx objectes, sinó que oferix serveis a les persones: el comerç, el transport, l’educació, la sanitat, el turisme o la banca. Una professora, un metge o una dependenta treballen en el sector terciari.\n\n'
  'El pes de cada sector ha canviat amb la història. Fa un segle, a Espanya, la majoria de la població treballava al camp. Amb la industrialització va créixer el sector secundari, i hui al voltant de tres de cada quatre treballadors es dediquen als serveis. Per això es diu que vivim en una economia terciaritzada.',
  [('A quin sector pertany la pesca?', ['Primari', 'Secundari', 'Terciari'], 0, 'El primari «obté els recursos directament de la natura».'),
   ('Una fàbrica de taulells de Castelló és un exemple del sector…', ['primari', 'secundari', 'terciari'], 1, 'El secundari «transforma eixes matèries primeres en productes elaborats».'),
   ('Què tenen en comú el turisme, la sanitat i l’educació?', ['Que obtenen recursos de la natura', 'Que oferixen serveis a les persones', 'Que fabriquen objectes'], 1, 'Són activitats del sector terciari, que «oferix serveis a les persones».'),
   ('Què vol dir que vivim en una economia terciaritzada?', ['Que la majoria treballa en els serveis', 'Que quasi tothom treballa al camp', 'Que hi ha tres tipus de fàbriques'], 0, '«Tres de cada quatre treballadors es dediquen als serveis.»')],
  {'subject': 'geohist', 'glossary': G(('matèria primera', 'Recurs natural que es transforma per a fabricar alguna cosa.'), ('béns', 'Objectes que es produïxen i es poden comprar.'), ('serveis', 'Treballs que es fan per a altres persones sense produir objectes.'), ('industrialització', 'Procés pel qual la indústria passa a ser una activitat principal.'))}),
 ('lectura_ca_eso_revolucio_industrial', 8, 'La Revolució Industrial', '🚂', ['historia', 'tecnologia'],
  'A finals del segle XVIII va començar a la Gran Bretanya una transformació tan profunda que es coneix com a Revolució Industrial. En poques dècades va canviar la manera de produir, de treballar i de viure, primer a Europa i després en bona part del món.\n\n'
  'El canvi fonamental va ser la mecanització: el treball que abans es feia a mà o amb la força dels animals el va començar a fer una màquina. L’invent clau va ser la màquina de vapor, millorada per James Watt en la segona meitat del segle XVIII, que cremava carbó per a produir moviment. Es va aplicar primer a la indústria tèxtil, on els nous telers fabricaven teles molt més de pressa i més barates que els artesans.\n\n'
  'La màquina de vapor també va transformar el transport. El ferrocarril i els vaixells de vapor van permetre portar matèries primeres i productes a llocs llunyans en poc de temps, i això va fer créixer el comerç.\n\n'
  'Les fàbriques es van instal·lar a les ciutats, i milers de llauradors hi van emigrar a la recerca de treball. Així es va formar una nova classe social, el proletariat. Les seues condicions eren molt dures: jornades de fins a catorze hores, salaris baixos, treball infantil i barris insalubres. Per a defendre els seus drets, els obrers es van organitzar en sindicats i, a poc a poc, van aconseguir millores com la reducció de la jornada laboral.\n\n'
  'Mentrestant, els propietaris de les fàbriques i dels bancs, la burgesia, es van enriquir i van guanyar poder polític. La societat va deixar de dividir-se pel naixement i va començar a dividir-se per la riquesa: era la societat de classes.',
  [('On i quan va començar la Revolució Industrial?', ['A França, en el segle XV', 'A la Gran Bretanya, a finals del segle XVIII', 'A Espanya, en el segle XX'], 1, '«A finals del segle XVIII va començar a la Gran Bretanya…»'),
   ('Què cremava la màquina de vapor per a produir moviment?', ['Carbó', 'Petroli', 'Gas natural'], 0, 'La màquina de vapor «cremava carbó per a produir moviment».'),
   ('Per què milers de llauradors van emigrar a les ciutats?', ['Per a buscar treball a les fàbriques', 'Perquè el camp estava prohibit', 'Per a estudiar a la universitat'], 0, '«Hi van emigrar a la recerca de treball.»'),
   ('Quin canvi social destaca l’últim paràgraf?', ['La societat va passar a dividir-se per la riquesa i no pel naixement', 'Van desaparéixer els rics', 'Els llauradors es van convertir en nobles'], 0, '«Va deixar de dividir-se pel naixement i va començar a dividir-se per la riquesa.»')],
  {'subject': 'geohist', 'glossary': G(('mecanització', 'Ús de màquines per a fer treballs que abans es feien a mà.'), ('proletariat', 'Classe social dels obrers que treballaven a canvi d’un salari.'), ('sindicat', 'Associació de treballadors que defén els seus drets.'), ('insalubre', 'Dolent per a la salut.'))}),
 ('lectura_ca_eso_adn', 8, 'L’ADN, el llibre d’instruccions', '🧬', ['ciencia'],
  'Per què tens els ulls del color dels de ta mare o els cabells arrissats com el teu iaio? La resposta és en l’ADN, una molècula que es troba en el nucli de quasi totes les teues cèl·lules i que conté la informació necessària per a construir i fer funcionar un ésser viu.\n\n'
  'L’ADN té forma de doble hèlix, com una escala de cargol. La seua estructura la van descriure el 1953 James Watson i Francis Crick, gràcies en gran part a les imatges de raigs X que va obtindre la científica Rosalind Franklin. Els esglaons d’eixa escala estan formats per quatre bases, representades per les lletres A, T, C i G. L’ordre en què apareixen funciona com un codi: igual que les lletres formen paraules, les bases formen instruccions.\n\n'
  'Un fragment d’ADN que conté la instrucció per a un caràcter concret s’anomena gen. Els éssers humans tenim uns vint mil gens, repartits en 46 cromosomes, és a dir, 23 parelles. De cada parella, un cromosoma ve de la mare i l’altre del pare. Per això ens assemblem a tots dos, però no som idèntics a cap.\n\n'
  'A mitjan segle XIX, sense saber res de l’ADN, el monjo Gregor Mendel ja havia descobert, encreuant plantes de pèsol, que alguns caràcters són dominants i altres recessius: un caràcter recessiu pot no notar-se en una generació i tornar a aparéixer en la següent. Hui la genètica permet diagnosticar malalties, millorar conreus i fins i tot resoldre delictes.',
  [('On es troba l’ADN?', ['Només a la sang', 'En el nucli de quasi totes les cèl·lules', 'Als ossos'], 1, '«Es troba en el nucli de quasi totes les teues cèl·lules.»'),
   ('Quina forma té la molècula d’ADN?', ['D’esfera', 'De doble hèlix', 'D’estrela'], 1, '«Té forma de doble hèlix, com una escala de cargol.»'),
   ('Per què ens assemblem al pare i a la mare, però no som idèntics a cap?', ['Perquè de cada parella de cromosomes, un ve de la mare i l’altre del pare', 'Perquè tenim més gens que ells', 'Perquè l’ADN canvia cada any'], 0, '«De cada parella, un cromosoma ve de la mare i l’altre del pare.»'),
   ('Què va descobrir Mendel amb les plantes de pèsol?', ['La forma de l’ADN', 'Que alguns caràcters són dominants i altres recessius', 'Com diagnosticar malalties'], 1, 'Va descobrir «que alguns caràcters són dominants i altres recessius».')],
  {'subject': 'bio', 'glossary': G(('molècula', 'Conjunt d’àtoms units.'), ('gen', 'Fragment d’ADN amb la informació d’un caràcter.'), ('cromosoma', 'Estructura del nucli formada per ADN molt enrotllat.'), ('recessiu', 'Caràcter que pot quedar amagat i només es nota si s’hereta del pare i de la mare.'))}),
 ('lectura_ca_eso_newton', 8, 'Les lleis del moviment', '🍏', ['ciencia'],
  'Una força és qualsevol acció capaç de canviar el moviment d’un cos o de deformar-lo. Empényer un carro, xutar una pilota o estirar una goma són exemples de forces. Es mesuren en newtons (N), en honor del científic anglés Isaac Newton, que el 1687 va publicar les tres lleis que expliquen com es mouen els cossos.\n\n'
  'La primera llei, o principi d’inèrcia, diu que un cos es manté en repòs o es mou en línia recta a velocitat constant si no hi actua cap força. Per això, quan un autobús frena de colp, els passatgers se’n van cap avant: el seu cos tendix a continuar movent-se.\n\n'
  'La segona llei relaciona la força amb l’acceleració, que és el canvi de velocitat. Com més gran és la força, més gran és l’acceleració; i com més massa té el cos, més força cal per a accelerar-lo. Es resumix en la fórmula F = m · a. Per això és més fàcil empényer un carro de la compra buit que un de ple.\n\n'
  'La tercera llei, o principi d’acció i reacció, afirma que quan un cos fa una força sobre un altre, este en fa una sobre el primer igual i de sentit contrari. Quan nadem, empenyem l’aigua cap arrere i l’aigua ens empeny cap avant. Els coets funcionen de la mateixa manera: expulsen gasos cap avall i els gasos els impulsen cap amunt.',
  [('En quina unitat es mesuren les forces?', ['En quilograms', 'En newtons', 'En metres'], 1, '«Es mesuren en newtons (N).»'),
   ('Quina llei explica que els passatgers se’n vagen cap avant quan l’autobús frena?', ['La primera, o principi d’inèrcia', 'La segona', 'La tercera'], 0, 'Per la inèrcia, «el seu cos tendix a continuar movent-se».'),
   ('Segons la segona llei, per què costa més empényer un carro ple?', ['Perquè té més massa i necessita més força per a accelerar', 'Perquè té menys inèrcia', 'Perquè el sòl és més llis'], 0, '«Com més massa té el cos, més força cal per a accelerar-lo.»'),
   ('Com explica la tercera llei que un coet puge?', ['Els gasos expulsats cap avall empenyen el coet cap amunt', 'El coet és més lleuger que l’aire', 'La gravetat desapareix'], 0, 'Acció i reacció: «expulsen gasos cap avall i els gasos els impulsen cap amunt».')],
  {'subject': 'fyq', 'glossary': G(('força', 'Acció que pot canviar el moviment o la forma d’un cos.'), ('inèrcia', 'Tendència d’un cos a continuar com està, quiet o en moviment.'), ('acceleració', 'Canvi de la velocitat d’un cos.'), ('massa', 'Quantitat de matèria d’un cos.'))}),
]
